#!/bin/bash
# The list of Facts
facts=("A ladybird might eat more than 5,000 insects in its lifetime!" "Fruit flies were the first living creatures to be sent into space." "Dragonflies have been on earth for 300 million years!" "A bee’s wings beat 190 times a second, that’s 11,400 times a minute." "The stag beetle is the largest species of insect to be found in the UK." "Caterpillars have 12 eyes!" "One dung beetle can drag 1,141 times its weight – that’s like a human pulling six double-decker buses!" "A single honeybee colony can produce around 100kg of honey each year – that’s 220 jars!" "An ant-eating assassin bug piles its victims onto its body to scare predators." "Large groups of fireflies sometimes flash in unison." "To breathe underwater, the water scorpion uses a snorkel-like tube on its abdomen." "There are 36 species of dragonfly found in the UK." "Bulldog ants can leap seven times the length of their bodies!" "Mosquitos are attracted to smelly feet!" "Some male stoneflies do push-ups to attract a mate." "Butterflies taste with their feet." "Grasshoppers have special organs in their hind legs that store energy for jumping." "A hornet’s favourite food is a…bee!" "The red postman butterfly develops its own poison by eating toxic plants!" "A sea skater’s leg hair traps air, enabling it to float on water." "Grasshoppers existed before dinosaurs!" "Ladybirds sometimes play dead to avoid predators." "Damselflies have been on earth for more than 300 million years." "Greater water boatmen breathe through their bottom!" "Male giraffe weevils use their long necks to fight each other.")
facts_length="${#facts[@]}"
random_selection=$(( RANDOM % $facts_length ))
eww update fact="${facts[$random_selection]}"